package fishmod.features.dungeon.f7

import com.mojang.blaze3d.vertex.PoseStack
import com.mojang.blaze3d.vertex.VertexConsumer
import fishmod.utils.Location
import fishmod.utils.Misc
import fishmod.utils.PingTracker
import fishmod.utils.Scheduler
import fishmod.utils.config.values.Floor7
import fishmod.utils.data.EntityUtil
import fishmod.utils.dungeon.Phase
import fishmod.utils.events.Events
import fishmod.utils.rendering.RenderUtils
import fishmod.utils.rendering.RenderingEvents
import net.fabricmc.fabric.api.client.rendering.v1.level.LevelRenderContext
import net.minecraft.client.Minecraft
import net.minecraft.core.component.DataComponents
import net.minecraft.network.chat.Component
import net.minecraft.network.protocol.game.ClientboundMoveEntityPacket
import net.minecraft.network.protocol.game.ClientboundRemoveEntitiesPacket
import net.minecraft.network.protocol.game.ClientboundSetEquipmentPacket
import net.minecraft.sounds.SoundEvents
import net.minecraft.world.entity.EquipmentSlot
import net.minecraft.world.entity.decoration.ArmorStand
import net.minecraft.world.entity.monster.zombie.Zombie
import net.minecraft.world.item.ItemStack
import net.minecraft.world.item.Items
import net.minecraft.world.phys.AABB
import net.minecraft.world.phys.Vec3
import java.util.concurrent.ConcurrentHashMap
import kotlin.math.ceil

/**
 * Blood room helper.
 *
 *  - **Watcher speed alert**: on "[BOSS] The Watcher: Let's see how you can handle this." the time
 *    since the blood door opened classifies the Watcher as fast / normal / slow (title + sound,
 *    optional party message), and a "Kill Mobs" title is scheduled for the predicted move tick.
 *  - **Blood mob predictor**: each blood mob (skull-tagged armor stand near the Watcher) has its
 *    travel direction integrated from its per-tick movement, and a box + line + countdown is drawn
 *    at the spot it will walk to so you can pre-aim. Constants (16.1 / 11.9 tick walk, 40 / 38 tick
 *    windows, the move-tick table) are calibrated — do not adjust.
 */
object BloodSolver {

    private const val OPEN_MESSAGE = "The BLOOD DOOR has been opened!"
    private const val WATCHER_MESSAGE = "[BOSS] The Watcher: Let's see how you can handle this."

    private var dungeonTick = 0
    private var bloodOpenTick = -1
    private var firstSpawns = true
    private var watcher: Zombie? = null
    private val bloodMobs = ConcurrentHashMap<ArmorStand, BloodEntity>()

    private class BloodEntity(val startVec: Vec3, val started: Int, val firstSpawn: Boolean) {
        var lastPosition: Vec3 = startVec
        val deltaHistory: ArrayDeque<Vec3> = ArrayDeque()
        var endVector: Vec3? = null
    }

    @JvmStatic
    fun init() {
        Events.ON_LOCATION_CHANGE.register { _ -> resetRun(); false }
        Events.ON_WORLD_CHANGE.register { resetRun(); false }

        Events.ON_SERVER_TICK.register {
            dungeonTick++
            val w = watcher
            if (w != null && w.isRemoved) { watcher = null; bloodMobs.clear() }
            bloodMobs.keys.removeAll { it.isRemoved || !it.isAlive }
            false
        }

        Events.ON_GAME_MESSAGE.register { message ->
            when (message.string) {
                OPEN_MESSAGE -> if (bloodOpenTick < 0) bloodOpenTick = dungeonTick
                WATCHER_MESSAGE -> if (Floor7.bloodSolverEnabled) onWatcherSpawn()
            }
            false
        }

        Events.ON_PACKET.register { packet ->
            when (packet) {
                is ClientboundSetEquipmentPacket -> {
                    if (watcher == null && Location.inDungeon()) {
                        val head = packet.slots.firstOrNull { it.first == EquipmentSlot.HEAD }?.second
                        if (head != null && !head.isEmpty && head.`is`(Items.PLAYER_HEAD)
                            && skullTexture(head) in WATCHER_SKULLS
                        ) {
                            watcher = Minecraft.getInstance().level?.getEntity(packet.entity) as? Zombie
                        }
                    }
                }
                is ClientboundRemoveEntitiesPacket -> {
                    val id = watcher?.id
                    if (id != null && packet.entityIds.any { it == id }) watcher = null
                }
                is ClientboundMoveEntityPacket -> onMobMove(packet)
            }
            false
        }

        RenderingEvents.NO_DEPTH_LINE.register { ctx, matrices, vc ->
            if (Floor7.bloodSolverEnabled && Location.inDungeon() && !Phase.inBoss() && bloodMobs.isNotEmpty()) {
                render(ctx, matrices, vc)
            }
        }
    }

    private fun resetRun() {
        dungeonTick = 0
        bloodOpenTick = -1
        firstSpawns = true
        watcher = null
        bloodMobs.clear()
    }

    /** "[BOSS] The Watcher: Let's see how you can handle this." — first wave is about to move. */
    private fun onWatcherSpawn() {
        firstSpawns = false
        if (bloodOpenTick < 0) return
        val seconds = (dungeonTick - bloodOpenTick) / 20

        if (Floor7.bloodSolverKillTitle) {
            val moveTicks = when (seconds) {
                in 31..33 -> 36
                in 28..30 -> 33
                in 25..27 -> 30
                in 22..24 -> 27
                in 1..21 -> 24
                else -> seconds + 3
            }
            Misc.addChatMessage(Component.literal("§bWatcher will move in §e${"%.2f".format(moveTicks / 20f)}s§b."))
            Scheduler.scheduleTask(Runnable { Misc.forceTitle(Component.literal("§c§lKill Mobs"), Component.empty()) }, moveTicks)
        }

        if (Floor7.bloodSolverSpeedAlert) {
            val title = if (seconds < 22) "§4§lFAST WATCHER" else if (seconds < 25) "§cNormal Watcher" else "§8Slow Watcher"
            val sound = if (seconds < 22) SoundEvents.TRIDENT_THUNDER.value()
            else if (seconds < 25) SoundEvents.WARDEN_DEATH else SoundEvents.VILLAGER_DEATH
            repeat(5) { Scheduler.scheduleSound(sound, 0.25f, 1f) }
            Misc.forceTitle(Component.literal(title), Component.empty())
            if (Floor7.bloodSolverSpeedAlertParty) Misc.executeCommand("pc $title")
        }
    }

    /**
     * Integrate each blood mob's travel direction from its per-move-entity packet (many
     * samples/tick → a stable direction), then project the walk endpoint spawnTime blocks along it
     * from the first-seen position. Fires pre-apply, so `stand.position()` + the packet delta is
     * the mob's new position.
     */
    private fun onMobMove(packet: ClientboundMoveEntityPacket) {
        if (!Floor7.bloodSolverEnabled || Phase.inBoss()) return
        if (packet.xa.toInt() == 0 && packet.ya.toInt() == 0 && packet.za.toInt() == 0) return
        val level = Minecraft.getInstance().level ?: return
        val w = watcher ?: return
        val stand = packet.getEntity(level) as? ArmorStand ?: return
        if (w.distanceToSqr(stand) > 400.0) return
        val head = stand.getItemBySlot(EquipmentSlot.HEAD)
        if (!head.`is`(Items.PLAYER_HEAD) || skullTexture(head) !in MOB_SKULLS) return

        val pos = Vec3(
            stand.x + packet.xa / 4096.0,
            stand.y + packet.ya / 4096.0,
            stand.z + packet.za / 4096.0,
        )
        val data = bloodMobs.getOrPut(stand) { BloodEntity(pos, dungeonTick, firstSpawns) }

        val delta = pos.subtract(data.lastPosition)
        data.lastPosition = pos
        if (delta.lengthSqr() > 0) data.deltaHistory.addLast(delta)

        val spawnTime = if (data.firstSpawn) 16.1 else 11.9
        val total = data.deltaHistory.fold(Vec3.ZERO) { acc, d -> acc.add(d) }
        if (total.lengthSqr() > 0) data.endVector = data.startVec.add(total.normalize().scale(spawnTime))
    }

    private fun render(ctx: LevelRenderContext, matrices: PoseStack, vc: VertexConsumer) {
        val decimals = Floor7.bloodSolverDecimals.coerceIn(0, 2)
        val ping = PingTracker.latest()
        val lineRgba = RenderUtils.toFloats(Floor7.bloodSolverLineColor)

        for ((stand, data) in bloodMobs) {
            val end = data.endVector ?: continue
            val timeTook = dungeonTick - data.started
            val time = (if (data.firstSpawn) 40 else 0) + 38 - timeTook + 0.8
            val secondsLeft = (time - 0.8) / 20.0

            val box = AABB(end.x - 0.5, end.y + 1.5, end.z - 0.5, end.x + 0.5, end.y + 2.5, end.z + 0.5)
            // Invert the box colour once ping outruns the remaining window — the endpoint is stale.
            var boxColor = Floor7.bloodSolverBoxColor
            if (ping > 0 && ping > time * 50) boxColor = boxColor xor 0x00FFFFFF

            RenderUtils.renderOutline(matrices, vc, box, RenderUtils.toFloats(boxColor))
            RenderUtils.renderLine(
                matrices, vc,
                EntityUtil.getLerpedPos(stand).add(0.0, 2.0, 0.0), end.add(0.0, 2.0, 0.0), lineRgba
            )

            val label = if (decimals > 0) "%.${decimals}f".format(secondsLeft) else ceil(secondsLeft).toInt().toString()
            RenderUtils.renderText(
                ctx, matrices,
                Component.literal(label).withColor(Floor7.bloodSolverTimerColor and 0xFFFFFF),
                end.add(0.0, 2.0, 0.0), 1.5f
            )
        }
    }

    private fun skullTexture(stack: ItemStack): String? {
        val profile = stack.get(DataComponents.PROFILE) ?: return null
        return profile.partialProfile().properties["textures"].firstOrNull()?.value()
    }

    // Base64 skull textures.
    private val WATCHER_SKULLS = setOf(
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        ""
    )

